<?php $me=current_user(); ?>
<section class="page-heading"><p class="eyebrow">JOURNEY LOG</p><h1>My bookings.</h1><p>Requests, confirmed seats, and journeys already travelled.</p></section>
<?php if(!$data['bookings']): ?><div class="empty-state"><h3>No bookings yet.</h3><p>Your ride requests and passenger bookings will appear here.</p><a href="index.php?page=find" class="btn btn-primary">Find a ride</a></div><?php else: ?><div class="booking-history"><?php foreach($data['bookings'] as $booking): $isPassenger=(int)$booking['passenger_id']===(int)$me['id']; ?><article class="history-card"><div class="booking-route"><strong><?= e($booking['origin']) ?> <span>→</span> <?= e($booking['destination']) ?></strong><small><?= e(date('D, M j',strtotime($booking['travel_date']))) ?> · <?= e(substr($booking['departure_time'],0,5)) ?> · <?= $isPassenger?'Driver '.e($booking['driver_name']):'Passenger '.e($booking['passenger_name']) ?></small></div><span class="status status-<?= strtolower($booking['status']) ?>"><?= e($booking['status']) ?></span><div class="row-actions"><?php if($isPassenger && in_array($booking['status'],['Pending','Confirmed'],true)): ?><form method="post" data-confirm="Cancel this booking?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel_booking"><input type="hidden" name="return_page" value="bookings"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><button class="btn btn-link btn-sm text-danger">Cancel booking</button></form><?php elseif(in_array($booking['status'],['Confirmed','Completed'],true)): ?><a class="btn btn-outline-dark btn-sm" href="index.php?page=chat&booking=<?= (int)$booking['id'] ?>">Message</a>
    <?php if($booking['status']==='Completed'): ?>
    <details class="review-details"><summary>Leave a review</summary><form method="post" class="review-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="review"><input type="hidden" name="return_page" value="bookings"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><label class="form-label" for="rating-<?= (int)$booking['id'] ?>">Rating</label><select class="form-select form-select-sm" id="rating-<?= (int)$booking['id'] ?>" name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Okay</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select><label class="form-label" for="comment-<?= (int)$booking['id'] ?>">Feedback</label><textarea class="form-control" id="comment-<?= (int)$booking['id'] ?>" name="comment" maxlength="1000" rows="2"></textarea><button class="btn btn-primary btn-sm mt-2">Submit review</button></form></details>
    <?php endif; ?>
  <?php endif; ?>
  </div>
</article>
<?php endforeach; ?>
</div>
<?php endif; ?>